/**
 * BHUMI Probabilistic Risk & Tier Utility
 *
 * Implements the 5-level risk classification based on actual forecast probabilities:
 * - low (< 20%)
 * - moderate (20% - 39.9%)
 * - elevated (40% - 59.9%)
 * - high (60% - 79.9%)
 * - very high (>= 80%)
 *
 * Enforces the Stale/Experimental Data Rule:
 * Predictions generated by an unready or experimental model must never be
 * displayed as validated production forecasts.
 */

import type { LivePredictionRow } from '@/lib/supabase/types';

export type RiskLevel = 'low' | 'moderate' | 'elevated' | 'high' | 'very_high';

export interface RiskMeta {
  level: RiskLevel;
  label: string;
  rangeText: string;
  description: string;
  hexColor: string;
  badgeClass: string;
  textClass: string;
  bgClass: string;
  borderClass: string;
}

