/**
 * Returns the 5-level risk classification for a probability percentage [0.0 - 100.0].
 */
export function getRiskLevel(probability: number | null | undefined): RiskLevel {
  if (probability === null || probability === undefined || isNaN(probability)) {
    return 'low';
  }
  const p = Math.max(0, Math.min(100, probability));
  if (p < 20) return 'low';
  if (p < 40) return 'moderate';
  if (p < 60) return 'elevated';
  if (p < 80) return 'high';
  return 'very_high';
}

export function getRiskMeta(level: RiskLevel): RiskMeta {
  return RISK_LEVELS[level] || RISK_LEVELS.low;
}

export function getRiskColorHex(probability: number | null | undefined): string {
  const level = getRiskLevel(probability);
  return RISK_LEVELS[level].hexColor;
}

export function formatProbability(value: number | null | undefined): string {
  if (value === null || value === undefined || isNaN(value)) {
    return 'N/A';
  }
  return `${Math.round(value * 10) / 10}%`;
}

export interface PredictionValidationStatus {
  isValid: boolean;
  tier: 'PRODUCTION' | 'EXPERIMENTAL' | 'UNAVAILABLE';
  badgeLabel: string;
  badgeVariant: 'default' | 'secondary' | 'outline' | 'destructive';
  notice: string;
  reasons: string[];
}

/**
 * Validates prediction provenance against authoritative model readiness.
 * Prevents presenting unready or experimental model output as validated production forecasts.
 */
export function evaluatePredictionTier(
  prediction: LivePredictionRow | null | undefined,
  isModelProductionReady: boolean = false
): PredictionValidationStatus {
  if (!prediction) {
    return {
      isValid: false,
      tier: 'UNAVAILABLE',
      badgeLabel: 'No Forecast Available',
      badgeVariant: 'outline',
      notice: 'No forecast data is currently available for this location.',
      reasons: ['Prediction record missing in public.live_predictions.'],
    };
  }

  const isTaggedExperimental =
    prediction.primary_driver?.includes('[EXPERIMENTAL]') ||
    prediction.advisory_code?.startsWith('exp_') ||
    !isModelProductionReady;

  if (isTaggedExperimental) {
    return {
      isValid: true,
      tier: 'EXPERIMENTAL',
      badgeLabel: 'Experimental Outlook',
      badgeVariant: 'secondary',
      notice:
        'Experimental Model Output — Historical training coverage is currently limited. This is not a validated production forecast.',
      reasons: [
        'National 4-class multi-season validation incomplete.',
        'Historical training archive coverage is limited.',
        'Stage 1 GRU disabled pending multi-decadal sequence training.',
      ],
    };

  }

  return {
    isValid: true,
    tier: 'PRODUCTION',
    badgeLabel: 'Operational Forecast',
    badgeVariant: 'default',
    notice: 'Calibrated operational forecast validated across historical seasons.',
    reasons: [],
  };
}
